IF	OBJECT_ID('tempdb..#tmpCustClass') IS NOT NULL
	DROP TABLE	#tmpCustClass;

CREATE TABLE #tmpCustClass(
	[CustId]			INT NOT NULL PRIMARY KEY,
	[CustomerClass]		SMALLINT
);

IF	OBJECT_ID('tempdb..#tmpCustCategoryByBatch') IS NOT NULL
	DROP TABLE	#tmpCustCategoryByBatch;

CREATE TABLE #tmpCustCategoryByBatch(
	[CustId]			INT NOT NULL PRIMARY KEY,
	[CustomerClass]		SMALLINT
);

INSERT INTO #tmpCustClass(CustId, CustomerClass)
SELECT	T.C.value('./@CustID', 'INT') AS CustId
	,	T.C.value('./@CustomerClass', 'SMALLINT') AS CustomerClass
FROM @CustCat.nodes('//Row') AS T(C)
OPTION (OPTIMIZE FOR (@CustCat = NULL));

DECLARE @BatchSize INT = 2000;

WHILE (EXISTS (SELECT 1 FROM #tmpCustClass WITH(NOLOCK)))
BEGIN
	DELETE TOP (@BatchSize) #tmpCustClass 
	OUTPUT DELETED.* 
	INTO #tmpCustCategoryByBatch;

	UPDATE c WITH(ROWLOCK, UPDLOCK)
	SET c.CustomerClass = b.CustomerClass
	FROM CustDB.dbo.CustInfo AS c
		INNER JOIN #tmpCustCategoryByBatch AS b ON c.CustId = b.CustId;
		
    TRUNCATE TABLE #tmpCustCategoryByBatch;
END;

DROP TABLE #tmpCustClass;
DROP TABLE #tmpCustCategoryByBatch;